/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
/// OCCT TODO CR27414 (ALL): Error : The area of result shape is
/// OCCT TODO CR27414 (ALL): Error : The volume of result shape is
/// OCCT TODO CR27414 (ALL): Error :  is WRONG because number of
#[ignore = "known failure in OCCT: CR27414"]
#[test]
fn xt1() -> DrawResult<()> {
    let mut d = Draw::new();
    d.polyline(&["p", "0", "0", "0", "0", "0", "10", "2", "0", "10", "2", "0", "2", "3", "0", "6", "5", "0", "6", "5", "0", "0", "0", "0", "0"])?;
    d.mkplane(&["f", "p"])?;
    d.prism(&["s", "f", "0", "5", "0"])?;
    d.offsetparameter(&["1e-7", "c", "i", "r"])?;
    d.offsetload(&["s", "1"])?;
    d.explode(&["s", "f"])?;
    d.nearest(&["s_4", "s", "F", "2.5", "2.5", "4.0", "20.6155"])?;
    d.offsetonface(&["s_4", "6"])?;
    d.offsetperform(&["result"])?;
    d.checkprops(&["result", "-s", "410", "-v", "504"])?;
    d.unifysamedom(&["result_unif", "result"])?;
    d.checknbshapes(&["result_unif", "-vertex", "12", "-edge", "18", "-wire", "8", "-face", "8", "-shell", "1", "-solid", "1"])?;
    Ok(())
}

