fn zy9() -> DrawResult<()> {
    let mut d = Draw::new();
    d.restore(&[data_file("bug26917_t114_c2.recipe_art1.brep").as_str(), "s"])?;
    d.offsetparameter(&["1.e-7", "c", "i", "r"])?;
    d.offsetload(&["s", "2"])?;
    d.offsetperform(&["result"])?;
    d.checkprops(&["result", "-s", "454.58", "-v", "475"])?;
    d.unifysamedom(&["result_unif", "result"])?;
    d.checknbshapes(&["result_unif", "-vertex", "14", "-edge", "21", "-wire", "9", "-face", "9", "-shell", "1"])?;
    Ok(())
}

